121	## 4. 创建流程实现
122	
123	### 4.1 surface_view_create() 完整流程
124	
125	```c
126	surface_view_t* surface_view_create(lv_obj_t* parent)
127	{
128	    surface_view_t* view = calloc(1, sizeof(surface_view_t));
129	    if (!view) return NULL;
130	
131	    view->parent   = parent;
132	    view->alpha    = 255;
133	    view->visible  = true;
134	    view->z_mode   = SURFACE_VIEW_Z_ABOVE_UI;
135	    view->format   = SURFACE_VIEW_FMT_RGB565;
136	    view->held_slot = -1;
137	
138	    /* === Step 1: 创建 LVGL 占位对象 === */
139	    view->obj = lv_obj_create(parent);
140	    lv_obj_remove_style_all(view->obj);  /* 清除所有默认样式 */
141	    lv_obj_set_style_bg_opa(view->obj, LV_OPA_TRANSP, 0);  /* 透明背景 */
142	    lv_obj_set_style_border_width(view->obj, 0, 0);
143	    lv_obj_set_style_pad_all(view->obj, 0, 0);
144	
145	    /* 存储 view 指针到 LVGL obj 的 user_data */
146	    lv_obj_set_user_data(view->obj, view);
147	
148	    /* 注册事件回调: 位置/大小变化、绘制、销毁 */
149	    lv_obj_add_event_cb(view->obj, on_size_changed,
150	        LV_EVENT_SIZE_CHANGED, view);
151	    lv_obj_add_event_cb(view->obj, on_draw_main,
152	        LV_EVENT_DRAW_MAIN, view);
153	    lv_obj_add_event_cb(view->obj, on_cover_check,
154	        LV_EVENT_COVER_CHECK, view);
155	    lv_obj_add_event_cb(view->obj, on_delete,
156	        LV_EVENT_DELETE, view);
157	
158	    /* === Step 2: 创建 BufferQueue === */
159	    int ret = bq_create(&view->producer, &view->consumer);
160	    if (ret != 0) {
161	        lv_obj_delete(view->obj);
162	        free(view);
163	        return NULL;
164	    }
165	
166	    /* === Step 3: 创建 BQ Surface (给 Camera/MediaPlayer 用) === */
167	    view->bq_surface = bq_producer_create_surface(view->producer);
168	
169	    /* === Step 4: 尝试获取 FB Overlay === */
170	    overlay_init(view);
171	
172	    /* === Step 5: 注册帧可用回调 === */
173	    bq_consumer_set_listener(view->consumer, on_frame_available, view);
174	
175	    return view;
176	}
177	```
