179	### 4.2 Overlay 初始化
180	
181	```c
182	/**
183	 * 尝试分配一个硬件 overlay 层
184	 * 如果硬件不支持或 overlay 已用完, 设置 hw_available = false,
185	 * 后续自动降级到 LVGL 软件渲染路径。
186	 */
187	static int overlay_init(surface_view_t* view)
188	{
189	    overlay_ctrl_t* ov = &view->overlay;
190	
191	    /* 打开 FB 设备 */
192	    ov->fb_fd = open("/dev/fb0", O_RDWR);
193	    if (ov->fb_fd < 0) {
194	        ov->hw_available = false;
195	        return -errno;
196	    }
197	
198	    /* 查询硬件支持的 overlay 数量 */
199	    struct fb_videoinfo_s vinfo;
200	    if (ioctl(ov->fb_fd, FBIOGET_VIDEOINFO, &vinfo) < 0 ||
201	        vinfo.noverlays < 2) {
202	        /* 无可用 overlay, 降级到软件模式 */
203	        ov->hw_available = false;
204	        close(ov->fb_fd);
205	        ov->fb_fd = -1;
206	        return -ENOTSUP;
207	    }
208	
209	    /* 分配一个空闲 overlay (简单策略: 从 1 开始找) */
210	    ov->overlay_id = overlay_allocate(ov->fb_fd, vinfo.noverlays);
211	    if (ov->overlay_id < 0) {
212	        ov->hw_available = false;
213	        close(ov->fb_fd);
214	        ov->fb_fd = -1;
215	        return -EBUSY;
216	    }
217	
218	    /* 选择该 overlay */
219	    ioctl(ov->fb_fd, FBIO_SELECT_OVERLAY, ov->overlay_id);
220	
221	    /* 获取 overlay buffer 信息 */
222	    memset(&ov->oinfo, 0, sizeof(ov->oinfo));
223	    ov->oinfo.overlay = ov->overlay_id;
224	    ioctl(ov->fb_fd, FBIOGET_OVERLAYINFO, &ov->oinfo);
225	
226	    /* 初始状态: 隐藏 (等首帧到了再显示) */
227	    ov->oinfo.blank = 1;
228	    ioctl(ov->fb_fd, FBIOSET_BLANK, &ov->oinfo);
229	
230	    /* 计算双缓冲后帧地址 */
231	    if (ov->oinfo.yres_virtual >= ov->oinfo.yres * 2) {
232	        ov->back_buffer = (uint8_t*)ov->oinfo.fbmem +
233	            ov->oinfo.stride * ov->oinfo.yres;
234	    } else {
235	        ov->back_buffer = ov->oinfo.fbmem;  /* 无双缓冲 */
236	    }
237	    ov->current_back = 0;
238	    ov->hw_available = true;
239	
240	    return 0;
241	}
242	
243	/**
244	 * 简单 overlay 分配: 扫描哪个 overlay 未被使用
245	 * 生产环境应有全局 overlay 分配器
246	 */
247	static int overlay_allocate(int fb_fd, int noverlays)
248	{
249	    struct fb_overlayinfo_s info;
250	    for (int i = 1; i < noverlays; i++) {
251	        memset(&info, 0, sizeof(info));
252	        info.overlay = i;
253	        if (ioctl(fb_fd, FBIOGET_OVERLAYINFO, &info) == 0) {
254	            if (info.blank != 0) {
255	                /* 这个 overlay 当前是 blank 的, 可以使用 */
256	                return i;
257	            }
258	        }
259	    }
260	    return -1;  /* 所有 overlay 都在使用中 */
261	}
262	```
