335	### 5.3 LV_EVENT_COVER_CHECK 回调
336	
337	```c
338	/**
339	 * Cover check — 告诉 LVGL 这个区域是否被完全覆盖
340	 *
341	 * 当 z_mode == Z_ABOVE_UI 时, SurfaceView 声明自己完全覆盖
342	 * 其区域, 这样 LVGL 可以跳过被遮挡区域的渲染 (优化)。
343	 *
344	 * 当 z_mode == Z_BELOW_UI 时, 声明不覆盖, LVGL 会继续
345	 * 渲染子对象 (UI 浮层) 在此区域之上。
346	 */
347	static void on_cover_check(lv_event_t* e)
348	{
349	    surface_view_t* view = lv_event_get_user_data(e);
350	    lv_event_set_cover_res(e,
351	        (view->z_mode == SURFACE_VIEW_Z_ABOVE_UI && view->overlay.hw_available)
352	            ? LV_COVER_RES_COVER      /* LVGL 可跳过此区域渲染 */
353	            : LV_COVER_RES_NOT_COVER  /* LVGL 需渲染此区域 */
354	    );
355	}
356	```
