360	## 6. 位置/大小同步机制
361	
362	### 6.1 核心问题
363	
364	LVGL 布局系统会动态计算 obj 的位置和大小（flex/grid/align 等），当 SurfaceView 的 obj 位置或大小变化时，必须同步更新 FB overlay 的 `darea`（目标显示区域），否则画面错位。
365	
366	### 6.2 LV_EVENT_SIZE_CHANGED 回调
367	
368	```c
369	/**
370	 * 位置/大小变化 → 同步 overlay darea
371	 *
372	 * LVGL 在以下情况触发 LV_EVENT_SIZE_CHANGED:
373	 *   - lv_obj_set_pos/size/align 显式设置
374	 *   - 父容器 layout 重新计算 (flex/grid)
375	 *   - 屏幕滚动导致可见区域变化
376	 */
377	static void on_size_changed(lv_event_t* e)
378	{
379	    surface_view_t* view = lv_event_get_user_data(e);
380	    lv_obj_t* obj = lv_event_get_target(e);
381	
382	    if (!view->overlay.hw_available) {
383	        return;  /* 软件模式不需要同步 overlay */
384	    }
385	
386	    /* 获取 obj 在屏幕上的绝对坐标 */
387	    lv_area_t coords;
388	    lv_obj_get_coords(obj, &coords);
389	
390	    int32_t abs_x = coords.x1;
391	    int32_t abs_y = coords.y1;
392	    int32_t width = lv_area_get_width(&coords);
393	    int32_t height = lv_area_get_height(&coords);
394	
395	    /* 更新 overlay 目标区域 */
396	    overlay_ctrl_t* ov = &view->overlay;
397	    ov->oinfo.darea.x = abs_x;
398	    ov->oinfo.darea.y = abs_y;
399	    ov->oinfo.darea.w = width;
400	    ov->oinfo.darea.h = height;
401	    ioctl(ov->fb_fd, FBIOSET_DESTAREA, &ov->oinfo);
402	
403	    /* 同时更新源区域 (BQ 帧对应的区域) */
404	    ov->oinfo.sarea.x = 0;
405	    ov->oinfo.sarea.y = 0;
406	    ov->oinfo.sarea.w = width;
407	    ov->oinfo.sarea.h = height;
408	    ioctl(ov->fb_fd, FBIOSET_AREA, &ov->oinfo);
409	
410	    /* 更新 BQ consumer 期望尺寸 (下一帧生效) */
411	    bq_consumer_set_default_size(view->consumer, width, height);
412	}
413	```
