477	### 7.2 on_frame_available 回调实现
478	
479	```c
480	/**
481	 * BQ frame-available 回调
482	 *
483	 * 注意: 此回调可能在任意线程上下文中触发（Camera Service 的工作线程）。
484	 * 不能直接操作 LVGL，需要通过 lv_async_call 切换到 LVGL 主线程。
485	 */
486	static void on_frame_available(void* user_data)
487	{
488	    surface_view_t* view = (surface_view_t*)user_data;
489	
490	    /* 切换到 LVGL 主线程处理 */
491	    lv_async_call(frame_commit_task, view);
492	}
493	
494	/**
495	 * 帧提交任务 — 在 LVGL 主线程中执行
496	 */
497	static void frame_commit_task(void* param)
498	{
499	    surface_view_t* view = (surface_view_t*)param;
500	
501	    if (!view->visible) return;
502	
503	    /* 释放上一帧持有的 buffer */
504	    release_held_buffer(view);
505	
506	    /* 排空 BQ, 仅保留最新帧 */
507	    bq_frame_info_t info;
508	    bq_frame_info_t latest = {0};
509	    bool has_frame = false;
510	
511	    while (bq_consumer_acquire_buffer(view->consumer, &info) == 0) {
512	        if (has_frame) {
513	            bq_consumer_release_buffer(view->consumer, latest.slot);
514	            graphic_buffer_release(latest.buffer);
515	        }
516	        latest = info;
517	        has_frame = true;
518	    }
519	
520	    if (!has_frame) return;
521	
522	    /* 锁定 buffer 获取 CPU 地址 */
523	    void* vaddr;
524	    if (graphic_buffer_lock(latest.buffer,
525	            GRALLOC_USAGE_SW_READ_OFTEN, &vaddr) != 0) {
526	        bq_consumer_release_buffer(view->consumer, latest.slot);
527	        graphic_buffer_release(latest.buffer);
528	        return;
529	    }
530	
531	    if (view->overlay.hw_available) {
532	        /* === HW Overlay 路径 === */
533	        commit_frame_to_overlay(view, vaddr, &latest);
534	        graphic_buffer_unlock(latest.buffer);
535	        bq_consumer_release_buffer(view->consumer, latest.slot);
536	        graphic_buffer_release(latest.buffer);
537	    } else {
538	        /* === SW Fallback 路径 (LVGL 渲染) === */
539	        /* 持有 buffer 直到下一帧 (零拷贝, img_dsc.data 指向它) */
540	        view->held_buffer = latest.buffer;
541	        view->held_slot = latest.slot;
542	        commit_frame_to_lvgl(view, vaddr, &latest);
543	        /* buffer 在下一次 frame_commit_task 中释放 */
544	    }
545	
546	    /* 首帧处理 */
547	    if (!view->has_first_frame) {
548	        view->has_first_frame = true;
549	        if (view->overlay.hw_available) {
550	            /* 显示 overlay (首帧到了才 unblank) */
551	            view->overlay.oinfo.blank = 0;
552	            ioctl(view->overlay.fb_fd, FBIOSET_BLANK, &view->overlay.oinfo);
553	        }
554	        /* 通知就绪 */
555	        if (view->ready_cb) {
556	            view->ready_cb(view, view->ready_ctx);
557	        }
558	    }
559	}
560	```
