562	### 7.3 HW Overlay 帧提交
563	
564	```c
565	/**
566	 * 将帧数据写入 FB overlay buffer 并触发显示
567	 */
568	static void commit_frame_to_overlay(surface_view_t* view,
569	    void* vaddr, const bq_frame_info_t* info)
570	{
571	    overlay_ctrl_t* ov = &view->overlay;
572	    uint32_t bpp = format_bpp(info->format);
573	    size_t frame_size = info->stride * info->height * bpp;
574	    void* target;
575	
576	    /* 双缓冲选择写入目标 */
577	    if (ov->back_buffer != ov->oinfo.fbmem) {
578	        /* 有双缓冲 */
579	        if (ov->current_back == 0) {
580	            target = ov->back_buffer;
581	            ov->oinfo.yoffset = ov->oinfo.yres;
582	        } else {
583	            target = ov->oinfo.fbmem;
584	            ov->oinfo.yoffset = 0;
585	        }
586	        ov->current_back = !ov->current_back;
587	    } else {
588	        /* 无双缓冲, 直接写 */
589	        target = ov->oinfo.fbmem;
590	        ov->oinfo.yoffset = 0;
591	    }
592	
593	    /* 帧数据拷贝 (或 DMA 如果可用) */
594	    memcpy(target, vaddr, frame_size);
595	
596	    /* 触发 Pan (切换显示到新写入的 buffer) */
597	    ioctl(ov->fb_fd, FBIOPAN_OVERLAY, &ov->oinfo);
598	}
