603	## 8. 软件回退路径（LVGL 渲染）
604	
605	当硬件 overlay 不可用时，SurfaceView 自动降级为在 LVGL 内部渲染。
606	
607	### 8.1 初始化 fallback 对象
608	
609	```c
610	/**
611	 * 在 overlay_init() 失败后调用
612	 * 创建 LVGL lv_image 对象作为帧显示容器
613	 */
614	static void setup_sw_fallback(surface_view_t* view)
615	{
616	    /* 在 SurfaceView obj 内部创建 lv_image */
617	    view->img_obj = lv_image_create(view->obj);
618	    lv_obj_set_size(view->img_obj, LV_PCT(100), LV_PCT(100));
619	    lv_obj_center(view->img_obj);
620	    lv_image_set_inner_align(view->img_obj, LV_IMAGE_ALIGN_STRETCH);
621	}
622	```
623	
624	### 8.2 SW 帧提交
625	
626	```c
627	/**
628	 * 软件路径: 将帧数据绑定到 LVGL img_dsc (零拷贝)
629	 */
630	static void commit_frame_to_lvgl(surface_view_t* view,
631	    void* vaddr, const bq_frame_info_t* info)
632	{
633	    if (view->img_obj == NULL) {
634	        setup_sw_fallback(view);
635	    }
636	
637	    if (info->format == HAL_PIXEL_FORMAT_YCBCR_420_888) {
638	        /* NV12 → LVGL (需 VG-Lite GPU 支持) */
639	        view->yuv_buf.semi_planar.y.buf = vaddr;
640	        view->yuv_buf.semi_planar.y.stride = info->stride;
641	        view->yuv_buf.semi_planar.uv.buf =
642	            (uint8_t*)vaddr + info->stride * info->height;
643	        view->yuv_buf.semi_planar.uv.stride = info->stride;
644	
645	        view->img_dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
646	        view->img_dsc.header.w = info->width;
647	        view->img_dsc.header.h = info->height;
648	        view->img_dsc.header.cf = LV_COLOR_FORMAT_NV12;
649	        view->img_dsc.header.stride = info->stride;
650	        view->img_dsc.data = (const uint8_t*)&view->yuv_buf;
651	    } else {
652	        /* RGB 路径 */
653	        uint32_t bpp = format_bpp(info->format);
654	        view->img_dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
655	        view->img_dsc.header.w = info->width;
656	        view->img_dsc.header.h = info->height;
657	        view->img_dsc.header.cf = hal_fmt_to_lv_cf(info->format);
658	        view->img_dsc.header.stride = info->stride * bpp;
659	        view->img_dsc.data_size = info->stride * info->height * bpp;
660	        view->img_dsc.data = (const uint8_t*)vaddr;
661	    }
662	
663	    lv_image_set_src(view->img_obj, &view->img_dsc);
664	    lv_obj_invalidate(view->img_obj);
665	}
666	```
