695	### 9.2 设置 Z-mode
696	
697	```c
698	int surface_view_set_z_mode(surface_view_t* view, surface_view_z_mode_t mode)
699	{
700	    if (!view) return -EINVAL;
701	    view->z_mode = mode;
702	
703	    if (!view->overlay.hw_available) return 0;
704	
705	    /*
706	     * Z_BELOW_UI: overlay 在 LVGL 层之下
707	     *   LCD 合成顺序: Overlay(底) → Primary FB/LVGL(顶)
708	     *   需要 LVGL 在 SurfaceView 区域"挖洞"(渲染透明)
709	     *   overlay z-order 设置为比 primary FB 低
710	     *
711	     * Z_ABOVE_UI: overlay 在 LVGL 层之上
712	     *   LCD 合成顺序: Primary FB/LVGL(底) → Overlay(顶)
713	     *   overlay 直接盖住 LVGL, 不需要挖洞
714	     *   overlay z-order 设置为比 primary FB 高
715	     *
716	     * 具体实现取决于硬件 LCD controller:
717	     *   - 有些硬件 overlay 固定在 primary 之上
718	     *   - 有些硬件支持动态调整层序
719	     *   - 通过 FB 驱动私有 ioctl 控制
720	     */
721	
722	    /* 触发 LVGL 重绘 (更新挖洞/不挖洞行为) */
723	    lv_obj_invalidate(view->obj);
724	
725	    return 0;
726	}
