733	### 10.1 销毁流程
734	
735	```c
736	/**
737	 * LV_EVENT_DELETE 回调 — LVGL obj 被删除时清理所有资源
738	 */
739	static void on_delete(lv_event_t* e)
740	{
741	    surface_view_t* view = lv_event_get_user_data(e);
742	
743	    /* 1. 停止帧接收 */
744	    bq_consumer_set_listener(view->consumer, NULL, NULL);
745	
746	    /* 2. 释放持有的 buffer */
747	    release_held_buffer(view);
748	
749	    /* 3. 隐藏并释放 overlay */
750	    if (view->overlay.hw_available) {
751	        view->overlay.oinfo.blank = 1;
752	        ioctl(view->overlay.fb_fd, FBIOSET_BLANK, &view->overlay.oinfo);
753	        close(view->overlay.fb_fd);
754	    }
755	
756	    /* 4. 销毁 BufferQueue */
757	    if (view->bq_surface) {
758	        bq_surface_destroy(view->bq_surface);
759	    }
760	    bq_producer_destroy(view->producer);
761	    bq_consumer_destroy(view->consumer);
762	
763	    /* 5. 释放 SurfaceView 结构体 */
764	    free(view);
765	}
766	
767	void surface_view_destroy(surface_view_t* view)
768	{
769	    if (!view) return;
770	    /* 删除 LVGL obj 会触发 LV_EVENT_DELETE → on_delete() */
771	    lv_obj_delete(view->obj);
772	}
