805	/**
806	 * 释放当前持有的 BQ buffer (软件模式下跨帧持有)
807	 */
808	static void release_held_buffer(surface_view_t* view)
809	{
810	    if (view->held_buffer != NULL) {
811	        graphic_buffer_unlock(view->held_buffer);
812	        bq_consumer_release_buffer(view->consumer, view->held_slot);
813	        graphic_buffer_release(view->held_buffer);
