819	/**
820	 * HAL pixel format → bytes per pixel
821	 */
822	static uint32_t format_bpp(int32_t format)
823	{
824	    switch (format) {
825	    case HAL_PIXEL_FORMAT_RGB_565:        return 2;
826	    case HAL_PIXEL_FORMAT_RGB_888:        return 3;
827	    case HAL_PIXEL_FORMAT_BGRA_8888:
828	    case HAL_PIXEL_FORMAT_RGBA_8888:      return 4;
829	    case HAL_PIXEL_FORMAT_YCBCR_420_888:  return 1;  /* NV12: 1.5 实际 */
830	    default:                              return 4;
831	    }
832	}
