835	 * HAL pixel format → LVGL color format
836	 */
837	static lv_color_format_t hal_fmt_to_lv_cf(int32_t format)
838	{
839	    switch (format) {
840	    case HAL_PIXEL_FORMAT_RGB_565:   return LV_COLOR_FORMAT_RGB565;
841	    case HAL_PIXEL_FORMAT_RGB_888:   return LV_COLOR_FORMAT_RGB888;
842	    case HAL_PIXEL_FORMAT_BGRA_8888: return LV_COLOR_FORMAT_ARGB8888;
843	    case HAL_PIXEL_FORMAT_YCBCR_420_888: return LV_COLOR_FORMAT_NV12;
844	    default:                         return LV_COLOR_FORMAT_ARGB8888;
